  1→/**
  2→ * @fileoverview Tool registry and execution entry point.
  3→ *
  4→ * Maintains the in-process registry for built-in and custom tools, validates
  5→ * input arguments, executes handlers, and exposes OpenAI-compatible schemas.
  6→ *
  7→ * @module tools/registry
  8→ */
  9→
 10→import { z } from 'zod';
 11→import { ToolResult, ToolContext, DangerLevel } from './types.js';
 12→import { logger } from '../utils/logger.js';
 13→import { ToolInputSchemas, type ToolName } from '../validation/tools.js';
 14→
 15→// Import tool handlers
 16→import {
 17→  handleWorkspaceList,
 18→  handleWorkspaceSelect,
 19→  handleWorkspaceStatus,
 20→  handleWorkspaceCreate,
 21→  handleWorkspaceDelete,
 22→  handleFileDelete,
 23→  handleFolderDelete,
 24→  handleWorkspaceSync,
 25→  handleWorkspacePublish,
 26→  workspaceTools,
 27→} from './workspace.js';
 28→
 29→import {
 30→  handleTaskCreate,
 31→  handleTaskStatus,
 32→  handleTaskCancel,
 33→  handleTaskRespond,
 34→  taskTools,
 35→} from './task.js';
 36→
 37→import {
 38→  handleAskUser,
 39→  handleReportProgress,
 40→  interactionTools,
 41→} from './interaction.js';
 42→
 43→import {
 44→  handleGitHubPRCreate,
 45→  handleGitHubPRList,
 46→  handleGitHubPRView,
 47→  handleGitHubIssueCreate,
 48→  handleGitHubIssueList,
 49→  handleGitHubBranchCreate,
 50→  handleGitHubActionStatus,
 51→  handleGitHubSearchRepos,
 52→  githubTools,
 53→} from './github.js';
 54→
 55→import {
 56→  handlePMList,
 57→  handlePMView,
 58→  handlePMComment,
 59→  handlePMUpdate,
 60→  pmTools,
 61→} from './pm.js';
 62→
 63→import {
 64→  handleWebFetch,
 65→  handleWebSearch,
 66→  webTools,
 67→} from './web.js';
 68→
 69→import {
 70→  handleBrowserOpen,
 71→  handleBrowserSnapshot,
 72→  handleBrowserAction,
 73→  handleBrowserScreenshot,
 74→  browserTools,
 75→} from './browser.js';
 76→
 77→import {
 78→  handleWorkflowCreate,
 79→  handleWorkflowList,
 80→  handleWorkflowRun,
 81→  handleWorkflowDelete,
 82→  handleCronCreate,
 83→  handleCronList,
 84→  handleCronDelete,
 85→  handleCronRun,
 86→  handleAppRun,
 87→  handleAppTest,
 88→  handleBrowserTest,
 89→  workflowTools,
 90→} from './workflow.js';
 91→
 92→import { loadToolDefinition, buildToolSchema, CustomToolDefinition } from './loader.js';
 93→import { loadTpmjsTools } from './tpmjs_loader.js';
 94→import { exec } from 'child_process';
 95→import util from 'util';
 96→const execPromise = util.promisify(exec);
 97→import chokidar from 'chokidar';
 98→import fs from 'fs';
 99→import { TOOLS_DIR, FETCH_CONFIG } from '../config/paths.js';
100→
101→// ============================================================================
102→// Internal Types
103→// ============================================================================
104→
105→/** Internal tool registration record used by the registry. */
106→export interface OrchestratorTool {
107→  /** Tool name */
108→  name: string; // broadened from ToolName for custom tools
109→  /** Tool description */
110→  description: string;
111→  /** Handler function */
112→  handler: (input: unknown, context?: ToolContext) => Promise<ToolResult>;
113→  /** Zod schema for validation */
114→  schema: z.ZodSchema;
115→  /** Safety level */
116→  danger?: DangerLevel;
117→  /** Is this a custom tool? */
118→  isCustom?: boolean;
119→}
120→
121→/** Async tool handler signature used by built-in and custom tools. */
122→export type ToolHandler = (input: unknown, context?: ToolContext) => Promise<ToolResult>;
123→
124→// ============================================================================
125→// Tool Registry Class
126→// ============================================================================
127→
128→export class ToolRegistry {
129→  private static instance: ToolRegistry | undefined;
130→  private tools: Map<string, OrchestratorTool> = new Map();
131→  private customToolFiles: Map<string, string> = new Map(); // filePath → toolName
132→  private customToolsDir: string;
133→  private watchers: ReturnType<typeof chokidar.watch>[] = [];
134→
135→  private tpmjsToolNames: Set<string> = new Set();
136→
137→  private constructor() {
138→    this.customToolsDir = TOOLS_DIR;
139→    this.registerBuiltins();
140→    this.initCustomTools();
141→    this.initTpmjsTools();
142→  }
143→
144→  private initCustomTools() {
145→    // Ensure dir exists (or try to)
146→    if (!fs.existsSync(this.customToolsDir)) {
147→      // Ideally we create it, but constructor sync content...
148→      // Async init pattern better, but singleton is sync accessed usually.
149→      // We'll set up watcher and let it fire on existing files if configured right.
150→    }
151→
152→    this.setupWatcher();
153→  }
154→
155→  /**
156→   * Asynchronously load TPMJS tools from fetch.config.json.
157→   * Runs in background — tools become available once fetched.
158→   */
159→  private initTpmjsTools() {
160→    loadTpmjsTools(FETCH_CONFIG).then((result) => {
161→      for (const { definition, schema } of result.tools) {
162→        const handler = this.createShellHandler(definition);
163→        this.register({
164→          name: definition.name,
165→          description: `[TPMJS] ${definition.description}`,
166→          handler,
167→          schema,
168→          danger: definition.danger,
169→          isCustom: true,
170→        });
171→        this.tpmjsToolNames.add(definition.name);
172→      }
173→
174→      if (result.tools.length > 0) {
175→        logger.info(`Loaded ${result.tools.length} TPMJS tools`, {
176→          tools: result.tools.map((t) => t.definition.name),
177→        });
178→      }
179→      if (result.failed.length > 0) {
180→        logger.warn(`${result.failed.length} TPMJS tools failed to load`, {
181→          failed: result.failed,
182→        });
183→      }
184→    }).catch((error) => {
185→      logger.error('Failed to initialize TPMJS tools', error);
186→    });
187→  }
188→
189→  /** Returns names of all currently loaded TPMJS tools. */
190→  public getTpmjsToolNames(): string[] {
191→    return Array.from(this.tpmjsToolNames);
192→  }
193→
194→  private setupWatcher() {
195→    try {
196→      const watcher = chokidar.watch(this.customToolsDir, {
197→        ignored: /(^|[/\\])\../,
198→        persistent: true,
199→        depth: 0
200→      });
201→
202→      watcher.on('add', (f) => this.loadCustomTool(f));
203→      watcher.on('change', (f) => this.loadCustomTool(f));
204→      watcher.on('unlink', (f) => this.unloadCustomTool(f));
205→
206→      this.watchers.push(watcher);
207→    } catch (err) {
208→      logger.error('Failed to setup tool watcher', err);
209→    }
210→  }
211→
212→  private async loadCustomTool(filePath: string) {
213→    if (!filePath.endsWith('.json')) return;
214→    const previousName = this.customToolFiles.get(filePath);
215→
216→    try {
217→      const def = await loadToolDefinition(filePath);
218→      if (!def) {
219→        if (previousName) {
220→          this.tools.delete(previousName);
221→          this.customToolFiles.delete(filePath);
222→          logger.info(`Custom tool unloaded due to invalid definition: ${previousName}`);
223→        }
224→        return;
225→      }
226→
227→      if (previousName && previousName !== def.name) {
228→        this.tools.delete(previousName);
229→        logger.info(`Custom tool renamed: ${previousName} -> ${def.name}`);
230→      }
231→
232→      const schema = buildToolSchema(def);
233→      const handler = this.createShellHandler(def);
234→
235→      const tool: OrchestratorTool = {
236→        name: def.name,
237→        description: def.description,
238→        danger: def.danger,
239→        schema,
240→        handler,
241→        isCustom: true
242→      };
243→
244→      this.register(tool);
245→      this.customToolFiles.set(filePath, def.name);
246→      logger.info(`Custom tool loaded: ${tool.name}`);
247→    } catch (error) {
248→      logger.error(`Failed to reload custom tool: ${filePath}`, { error });
249→      if (previousName) {
250→        this.tools.delete(previousName);
251→        this.customToolFiles.delete(filePath);
252→        logger.info(`Custom tool unloaded after reload failure: ${previousName}`);
253→      }
254→    }
255→  }
256→
257→  private unloadCustomTool(filePath: string) {
258→    const toolName = this.customToolFiles.get(filePath);
259→    if (toolName) {
260→      this.tools.delete(toolName);
261→      this.customToolFiles.delete(filePath);
262→      logger.info(`Custom tool unloaded: ${toolName}`);
263→    }
264→  }
265→
266→  private createShellHandler(def: CustomToolDefinition): ToolHandler {
267→    return async (input: unknown) => {
268→      const params = input as Record<string, unknown>;
269→      let command = def.command;
270→
271→      // Template replacement: {{param}} with shell-safe escaping
272→      Object.keys(params).forEach(key => {
273→        const val = String(params[key]);
274→        // Escape single quotes and wrap in single quotes for shell safety
275→        const escaped = "'" + val.replace(/'/g, "'\\''") + "'";
276→        command = command.replace(new RegExp(`{{${key}}}`, 'g'), escaped);
277→      });
278→
279→      const MAX_SHELL_OUTPUT = 100_000;
280→      const start = Date.now();
281→      try {
282→        const cwd = def.cwd || process.cwd();
283→        const { stdout, stderr } = await execPromise(command, { cwd });
284→        const truncatedOutput = (stdout || stderr || 'Command executed successfully').slice(0, MAX_SHELL_OUTPUT);
285→
286→        return {
287→          success: true,
288→          output: truncatedOutput,
289→          duration: Date.now() - start
290→        };
291→      } catch (error) {
292→        const err = error as { stdout?: string; message?: string; stderr?: string };
293→        return {
294→          success: false,
295→          output: err.stdout || '',
296→          error: err.message || err.stderr || 'Unknown execution error',
297→          duration: Date.now() - start
298→        };
299→      }
300→    };
301→  }
302→
303→  public static getInstance(): ToolRegistry {
304→    if (!ToolRegistry.instance) {
305→      ToolRegistry.instance = new ToolRegistry();
306→    }
307→    return ToolRegistry.instance;
308→  }
309→
310→  /** Closes custom-tool watchers and releases watcher resources. */
311→  public async shutdown(): Promise<void> {
312→    for (const watcher of this.watchers) {
313→      await watcher.close();
314→    }
315→    this.watchers = [];
316→  }
317→
318→  /** Registers one tool definition (insert/replace by tool name). */
319→  public register(tool: OrchestratorTool): void {
320→    this.tools.set(tool.name, tool);
321→    logger.debug(`Registered tool: ${tool.name}`);
322→  }
323→
324→  /** Registers a dictionary of tools. */
325→  public registerAll(tools: Record<string, OrchestratorTool>): void {
326→    for (const tool of Object.values(tools)) {
327→      this.register(tool);
328→    }
329→  }
330→
331→  /** Returns one tool by name, if registered. */
332→  public get(name: string): OrchestratorTool | undefined {
333→    return this.tools.get(name);
334→  }
335→
336→  /** Returns all currently registered tools. */
337→  public list(): OrchestratorTool[] {
338→    return Array.from(this.tools.values());
339→  }
340→
341→  /** Returns registered tools in OpenAI function-calling format. */
342→  // eslint-disable-next-line @typescript-eslint/no-explicit-any
343→  public toOpenAIFormat(toolNames?: string[]): any[] {
344→    const selected = toolNames && toolNames.length > 0
345→      ? toolNames
346→        .map((name) => this.tools.get(name))
347→        .filter((tool): tool is OrchestratorTool => !!tool)
348→      : Array.from(this.tools.values());
349→    const result = selected.map(tool => _mapToOpenAIFunction(tool));
350→
351→    // Log schemas once on first call for debugging
352→    if (!this._schemaLogged) {
353→      this._schemaLogged = true;
354→      for (const tool of result) {
355→        // eslint-disable-next-line @typescript-eslint/no-explicit-any
356→        const fn = (tool as any).function;
357→        logger.debug('Tool schema', {
358→          name: fn?.name,
359→          parameters: JSON.stringify(fn?.parameters),
360→        });
361→      }
362→    }
363→
364→    return result;
365→  }
366→
367→  private _schemaLogged = false;
368→
369→  /** Validates input and executes a registered tool handler by name. */
370→  public async execute(name: string, args: unknown, context?: ToolContext): Promise<ToolResult> {
371→    const tool = this.tools.get(name);
372→    logger.info(`ToolRegistry.execute called: ${name}`, { found: !!tool, hasHandler: !!tool?.handler });
373→    if (!tool) {
374→      return {
375→        success: false,
376→        output: `Tool '${name}' not found`,
377→        duration: 0
378→      };
379→    }
380→
381→    const startTime = Date.now();
382→    try {
383→      const autonomyLevel = context?.autonomyLevel ?? 'cautious';
384→
385→      // Enforce autonomy policy before schema/handler execution.
386→      // This is a hard safety layer independent of prompt behavior.
387→      if (tool.danger === DangerLevel.DANGEROUS) {
388→        if (autonomyLevel === 'supervised') {
389→          return {
390→            success: false,
391→            output: `Safety policy blocked dangerous tool '${name}' in supervised mode. Request explicit operator intervention or switch autonomy level.`,
392→            duration: Date.now() - startTime,
393→          };
394→        }
395→        if (autonomyLevel === 'cautious' && !hasExplicitConfirmation(args)) {
396→          return {
397→            success: false,
398→            output: `Tool '${name}' requires manual confirmation in Cautious Mode. You MUST use the 'ask_user' tool to request permission from the operator explaining exactly what you intend to do. If they approve, retry this action with 'confirm: true'.`,
399→            duration: Date.now() - startTime,
400→          };
401→        }
402→      }
403→
404→      // Validate args with Zod safeParse — lets the LLM self-correct bad arguments
405→      const validation = tool.schema.safeParse(args);
406→      if (!validation.success) {
407→        const issues = validation.error.issues
408→          .map((i) => `${i.path.join('.')}: ${i.message}`)
409→          .join('; ');
410→        logger.warn(`Tool validation failed: ${name}`, { issues });
411→        return {
412→          success: false,
413→          output: `Validation error for tool '${name}': ${issues}. Please fix the arguments and try again.`,
414→          duration: Date.now() - startTime
415→        };
416→      }
417→
418→      const result = await tool.handler(validation.data, context);
419→      // Ensure duration is present if tool doesn't provide it
420→      if (result.duration === undefined) {
421→        result.duration = Date.now() - startTime;
422→      }
423→      return result;
424→    } catch (error) {
425→      logger.error(`Tool execution failed: ${name}`, { error });
426→      return {
427→        success: false,
428→        output: `Error executing tool '${name}': ${error instanceof Error ? error.message : String(error)}`,
429→        duration: Date.now() - startTime
430→      };
431→    }
432→  }
433→
434→  private registerBuiltins(): void {
435→    const builtins: Record<string, { h: ToolHandler; s: z.ZodSchema; d: DangerLevel }> = {
436→      // WORKSPACE
437→      workspace_list: { h: handleWorkspaceList, s: ToolInputSchemas.workspace_list, d: DangerLevel.SAFE },
438→      workspace_select: { h: handleWorkspaceSelect, s: ToolInputSchemas.workspace_select, d: DangerLevel.SAFE },
439→      workspace_status: { h: handleWorkspaceStatus, s: ToolInputSchemas.workspace_status, d: DangerLevel.SAFE },
440→      workspace_create: { h: handleWorkspaceCreate, s: ToolInputSchemas.workspace_create, d: DangerLevel.MODERATE },
441→      workspace_delete: { h: handleWorkspaceDelete, s: ToolInputSchemas.workspace_delete, d: DangerLevel.DANGEROUS },
442→      file_delete: { h: handleFileDelete, s: ToolInputSchemas.file_delete, d: DangerLevel.DANGEROUS },
443→      folder_delete: { h: handleFolderDelete, s: ToolInputSchemas.folder_delete, d: DangerLevel.DANGEROUS },
444→      workspace_sync: { h: handleWorkspaceSync, s: ToolInputSchemas.workspace_sync, d: DangerLevel.MODERATE },
445→      workspace_publish: { h: handleWorkspacePublish, s: ToolInputSchemas.workspace_publish, d: DangerLevel.MODERATE },
446→
447→      // TASK
448→      task_create: { h: handleTaskCreate, s: ToolInputSchemas.task_create, d: DangerLevel.MODERATE },
449→      task_status: { h: handleTaskStatus, s: ToolInputSchemas.task_status, d: DangerLevel.SAFE },
450→      task_cancel: { h: handleTaskCancel, s: ToolInputSchemas.task_cancel, d: DangerLevel.MODERATE },
451→      task_respond: { h: handleTaskRespond, s: ToolInputSchemas.task_respond, d: DangerLevel.SAFE },
452→
453→      // INTERACTION
454→      ask_user: { h: handleAskUser, s: ToolInputSchemas.ask_user, d: DangerLevel.SAFE },
455→      report_progress: { h: handleReportProgress, s: ToolInputSchemas.report_progress, d: DangerLevel.SAFE },
456→
457→      // GITHUB
458→      github_pr_create: { h: handleGitHubPRCreate, s: ToolInputSchemas.github_pr_create, d: DangerLevel.MODERATE },
459→      github_pr_list: { h: handleGitHubPRList, s: ToolInputSchemas.github_pr_list, d: DangerLevel.SAFE },
460→      github_pr_view: { h: handleGitHubPRView, s: ToolInputSchemas.github_pr_view, d: DangerLevel.SAFE },
461→      github_issue_create: { h: handleGitHubIssueCreate, s: ToolInputSchemas.github_issue_create, d: DangerLevel.MODERATE },
462→      github_issue_list: { h: handleGitHubIssueList, s: ToolInputSchemas.github_issue_list, d: DangerLevel.SAFE },
463→      github_branch_create: { h: handleGitHubBranchCreate, s: ToolInputSchemas.github_branch_create, d: DangerLevel.MODERATE },
464→      github_action_status: { h: handleGitHubActionStatus, s: ToolInputSchemas.github_action_status, d: DangerLevel.SAFE },
465→      github_search_repos: { h: handleGitHubSearchRepos, s: ToolInputSchemas.github_search_repos, d: DangerLevel.SAFE },
466→
467→      // PM
468→      pm_list: { h: handlePMList, s: ToolInputSchemas.pm_list, d: DangerLevel.SAFE },
469→      pm_view: { h: handlePMView, s: ToolInputSchemas.pm_view, d: DangerLevel.SAFE },
470→      pm_comment: { h: handlePMComment, s: ToolInputSchemas.pm_comment, d: DangerLevel.MODERATE },
471→      pm_update: { h: handlePMUpdate, s: ToolInputSchemas.pm_update, d: DangerLevel.MODERATE },
472→
473→      // WEB
474→      web_fetch: { h: handleWebFetch, s: ToolInputSchemas.web_fetch, d: DangerLevel.SAFE },
475→      web_search: { h: handleWebSearch, s: ToolInputSchemas.web_search, d: DangerLevel.SAFE },
476→
477→      // BROWSER
478→      browser_open: { h: handleBrowserOpen, s: ToolInputSchemas.browser_open, d: DangerLevel.MODERATE },
479→      browser_snapshot: { h: handleBrowserSnapshot, s: ToolInputSchemas.browser_snapshot, d: DangerLevel.SAFE },
480→      browser_action: { h: handleBrowserAction, s: ToolInputSchemas.browser_action, d: DangerLevel.MODERATE },
481→      browser_screenshot: { h: handleBrowserScreenshot, s: ToolInputSchemas.browser_screenshot, d: DangerLevel.SAFE },
482→      // WORKFLOW / CRON / RUNTIME
483→      workflow_create: { h: handleWorkflowCreate, s: ToolInputSchemas.workflow_create, d: DangerLevel.MODERATE },
484→      workflow_list: { h: handleWorkflowList, s: ToolInputSchemas.workflow_list, d: DangerLevel.SAFE },
485→      workflow_run: { h: handleWorkflowRun, s: ToolInputSchemas.workflow_run, d: DangerLevel.MODERATE },
486→      workflow_delete: { h: handleWorkflowDelete, s: ToolInputSchemas.workflow_delete, d: DangerLevel.MODERATE },
487→      cron_create: { h: handleCronCreate, s: ToolInputSchemas.cron_create, d: DangerLevel.MODERATE },
488→      cron_list: { h: handleCronList, s: ToolInputSchemas.cron_list, d: DangerLevel.SAFE },
489→      cron_delete: { h: handleCronDelete, s: ToolInputSchemas.cron_delete, d: DangerLevel.MODERATE },
490→      cron_run: { h: handleCronRun, s: ToolInputSchemas.cron_run, d: DangerLevel.MODERATE },
