494→    };
495→
496→    for (const [name, meta] of Object.entries(builtins)) {
497→      const wTools = workspaceTools as Record<string, { description: string }>;
498→      const tTools = taskTools as Record<string, { description: string }>;
499→      const iTools = interactionTools as Record<string, { description: string }>;
500→      const gTools = githubTools as Record<string, { description: string }>;
501→      const pTools = pmTools as Record<string, { description: string }>;
502→      const webT = webTools as Record<string, { description: string }>;
503→      const brT = browserTools as Record<string, { description: string }>;
504→      const wfT = workflowTools as Record<string, { description: string }>;
505→
506→      const description = (wTools[name] || tTools[name] || iTools[name] || gTools[name] || pTools[name] || webT[name] || brT[name] || wfT[name])?.description || 'No description';
507→      logger.info(`Registering builtin tool: ${name}`, { hasHandler: !!meta.h });
508→
509→      this.register({
510→        name: name as ToolName,
511→        description,
512→        handler: meta.h,
513→        schema: meta.s,
514→        danger: meta.d
515→      });
516→    }
517→  }
518→}
519→
520→// ============================================================================
521→// Utility Functions
522→// ============================================================================
523→
524→function hasExplicitConfirmation(args: unknown): boolean {
525→  if (!args || typeof args !== 'object') return false;
526→  const record = args as Record<string, unknown>;
527→  return record.confirm === true;
528→}
529→
530→function _mapToOpenAIFunction(tool: OrchestratorTool): Record<string, unknown> {
531→  return {
532→    type: 'function',
533→    function: {
534→      name: tool.name,
535→      description: tool.description,
536→      parameters: zodToJsonSchema(tool.schema),
537→    },
538→  };
539→}
540→
541→function zodToJsonSchema(schema: z.ZodSchema): Record<string, unknown> {
542→  // Zod v4: use .type and .def instead of ._def.typeName
543→  // eslint-disable-next-line @typescript-eslint/no-explicit-any
544→  const s = schema as any;
545→
546→  if (s.type === 'object' && s.def?.shape) {
547→    const shape = s.def.shape;
548→    const properties: Record<string, unknown> = {};
549→    const required: string[] = [];
550→
551→    for (const [key, value] of Object.entries(shape)) {
552→      // eslint-disable-next-line @typescript-eslint/no-explicit-any
553→      const field = value as any;
554→
555→      // Use Zod v4's built-in isOptional() method
556→      const isOptional = typeof field.isOptional === 'function' ? field.isOptional() : false;
557→
558→      // Unwrap wrapper types to get the core type
559→      const innerSchema = unwrapZodType(field);
560→      properties[key] = zodTypeToJsonSchema(innerSchema, field);
561→
562→      if (!isOptional) required.push(key);
563→    }
564→
565→    const result: Record<string, unknown> = { type: 'object', properties };
566→    if (required.length > 0) result.required = required;
567→    return result;
568→  }
569→  return { type: 'object', properties: {} };
570→}
571→
572→/** Unwraps default/optional/nullable wrappers to reach core Zod type. */
573→// eslint-disable-next-line @typescript-eslint/no-explicit-any
574→function unwrapZodType(schema: any): any {
575→  let current = schema;
576→  while (current) {
577→    const type = current.type ?? current.def?.type;
578→    if (type === 'default' || type === 'optional' || type === 'nullable') {
579→      current = current.def?.innerType ?? current._def?.innerType;
580→    } else {
581→      return current;
582→    }
583→  }
584→  return schema;
585→}
586→
587→/** Converts one Zod field schema into JSON-schema-like descriptor. */
588→// eslint-disable-next-line @typescript-eslint/no-explicit-any
589→function zodTypeToJsonSchema(innerSchema: any, outerSchema?: any): Record<string, unknown> {
590→  const base: Record<string, unknown> = {};
591→
592→  // In Zod v4, .description is a direct property, also available via .meta()
593→  const desc = outerSchema?.description ?? innerSchema?.description;
594→  if (desc) base.description = desc;
595→
596→  const type = innerSchema?.type ?? innerSchema?.def?.type;
597→
598→  switch (type) {
599→    case 'string': return { ...base, type: 'string' };
600→    case 'number': return { ...base, type: 'number' };
601→    case 'boolean': return { ...base, type: 'boolean' };
602→    case 'enum': {
603→      // Zod v4: enum entries are in .def.entries as { key: value } or .values as array
604→      const entries = innerSchema.def?.entries;
605→      const values = entries ? Object.values(entries) : (innerSchema.values ?? innerSchema.options);
606→      return values ? { ...base, type: 'string', enum: values } : { ...base, type: 'string' };
607→    }
608→    case 'array': {
609→      const itemSchema = innerSchema.def?.element ?? innerSchema.def?.type;
610→      return { ...base, type: 'array', items: itemSchema ? zodTypeToJsonSchema(unwrapZodType(itemSchema)) : { type: 'string' } };
611→    }
612→    default: return { ...base, type: 'string' };
613→  }
614→}
